const body = $input.first().json.body || $input.first().json;
const ar = (body.lang || 'ar') === 'ar';
const esc = x => String(x ?? '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));

const name = body.name || '';
const email = body.email || '';
const score = body.score ?? 0;
const total = body.total ?? 0;
const percent = body.percent ?? 0;
const examTitle = body.examTitle || (ar ? 'امتحان' : 'Exam');
const examId = body.examId || '';
const results = Array.isArray(body.results) ? body.results : [];
const timestamp = new Date().toISOString();

const L = ar ? {
  brand: 'صانع الامتحانات',
  hi: 'أهلاً',
  result: 'نتيجتك في الامتحان',
  score: 'الدرجة',
  of: 'من',
  pct: 'النسبة',
  your: 'إجابتك',
  correct: 'الإجابة الصحيحة',
  why: 'التوضيح',
  ok: 'صحيح',
  bad: 'خطأ',
  summary: 'ملخص أدائك'
} : {
  brand: 'Exam Maker',
  hi: 'Hello',
  result: 'Your exam result',
  score: 'Score',
  of: 'of',
  pct: 'Percentage',
  your: 'Your answer',
  correct: 'Correct answer',
  why: 'Explanation',
  ok: 'Correct',
  bad: 'Wrong',
  summary: 'Performance summary'
};

const items = results.map((r, i) => {
  const tagBg = r.correct ? '#d1fae5' : '#fee2e2';
  const tagColor = r.correct ? '#065f46' : '#991b1b';
  const tag = r.correct ? L.ok : L.bad;
  let extra = '';
  if (!r.correct) {
    extra += `<div style="color:#4b5563;margin-top:4px"><b>${L.correct}:</b> ${esc(r.correctAnswer)}</div>`;
  }
  if (r.explanation) {
    extra += `<div style="margin-top:6px;padding:8px 12px;border-radius:8px;background:#ecfdf5;color:#0f766e;font-size:13px"><b>${L.why}:</b> ${esc(r.explanation)}</div>`;
  }
  return `<div style="padding:14px 0;border-top:1px solid #e5e7eb">
    <span style="display:inline-block;font-size:11px;font-weight:700;padding:2px 8px;border-radius:99px;background:${tagBg};color:${tagColor};margin-bottom:6px">${tag}</span>
    <div style="font-weight:700;font-size:15px;color:#0f172a;margin-bottom:6px">${i+1}. ${esc(r.q)}</div>
    <div style="color:#4b5563"><b>${L.your}:</b> ${esc(r.userAnswer) || '—'}</div>
    ${extra}
  </div>`;
}).join('');

const html = `<div dir="${ar?'rtl':'ltr'}" style="background:#0a1018;padding:28px 16px;font-family:Tahoma,Arial,sans-serif">
  <div style="max-width:640px;margin:auto;background:#111a24;border:1px solid rgba(160,200,240,0.15);border-radius:18px;overflow:hidden">
    <div style="background:linear-gradient(140deg,#14b8a6,#0d9488);color:#042f2e;padding:18px 28px;font-size:18px;font-weight:700">${L.brand}</div>
    <div style="padding:28px">
      <h1 style="margin:0 0 8px;font-size:22px;color:#e8f0f8">${L.result}</h1>
      <p style="color:#8fa3b8;margin:0 0 20px">${L.hi} ${esc(name)} — ${esc(examTitle)}</p>
      <div style="text-align:center;margin:20px 0 28px;padding:24px;background:rgba(45,212,191,0.1);border:1px solid rgba(45,212,191,0.35);border-radius:16px">
        <div style="font-size:42px;font-weight:700;color:#2dd4bf;line-height:1">${score} <span style="font-size:18px;color:#8fa3b8">${L.of} ${total}</span></div>
        <div style="margin-top:8px;font-size:16px;font-weight:600;color:#38bdf8">${L.pct}: ${percent}%</div>
      </div>
      <h2 style="font-size:15px;color:#e8f0f8;margin:0 0 8px;border-bottom:1px solid rgba(160,200,240,0.12);padding-bottom:8px">${L.summary}</h2>
      <div style="background:#f8fafc;border-radius:12px;padding:8px 16px;color:#0f172a">${items}</div>
    </div>
  </div>
</div>`;

const subject = ar
  ? `نتيجتك: ${score}/${total} (${percent}%) — ${examTitle}`
  : `Your result: ${score}/${total} (${percent}%) — ${examTitle}`;

return [{
  json: {
    timestamp,
    examId,
    name,
    email,
    score: String(score),
    total: String(total),
    percent: String(percent),
    html,
    subject,
    emailTo: email
  }
}];
